	val, ok := s.StrategyOptions["full_transcript_generation_retention_days"]
	if !ok {
		return defaultGenerationRetentionDays
	}

	switch days := val.(type) {
	case int:
		if days > 0 {
			return days
		}
	case float64:
		intDays := int(days)
		if intDays > 0 && days == float64(intDays) {
			return intDays
		}
	}

	return defaultGenerationRetentionDays
}

