-	output, err := remote.LsRemoteInDir(ctx, repoPath, fetchTarget, refName)
-	if err != nil {
-		return plumbing.ZeroHash, fmt.Errorf("git ls-remote %s failed: %w", remote.RedactURL(fetchTarget), err)
